import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"📋 Asignación: Exposición y Defensa Práctica (Evaluación 3)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-V/Asignacion_Exposicion_Evaluacion_3.md","filePath":"materias/Redes/documentacion/II-V/Asignacion_Exposicion_Evaluacion_3.md"}'),r={name:"materias/Redes/documentacion/II-V/Asignacion_Exposicion_Evaluacion_3.md"};function n(s,e,l,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="📋-asignacion-exposicion-y-defensa-practica-evaluacion-3" tabindex="-1">📋 Asignación: Exposición y Defensa Práctica (Evaluación 3) <a class="header-anchor" href="#📋-asignacion-exposicion-y-defensa-practica-evaluacion-3" aria-label="Permalink to &quot;📋 Asignación: Exposición y Defensa Práctica (Evaluación 3)&quot;">​</a></h1><p><strong>Materia:</strong> Redes (Trayecto II) <strong>Eje Temático:</strong> Administración y Servicios Vitales de Red</p><h2 id="🎯-objetivo-de-la-evaluacion" tabindex="-1">🎯 Objetivo de la Evaluación <a class="header-anchor" href="#🎯-objetivo-de-la-evaluacion" aria-label="Permalink to &quot;🎯 Objetivo de la Evaluación&quot;">​</a></h2><p>Demostrar el dominio teórico de los servicios de red fundamentales (Capa 7) y contrastar la experiencia práctica de administrar un servidor web de alto rendimiento (<strong>Nginx</strong>) en entornos Windows y Linux, fomentando la investigación autónoma.</p><h2 id="👥-modalidad" tabindex="-1">👥 Modalidad <a class="header-anchor" href="#👥-modalidad" aria-label="Permalink to &quot;👥 Modalidad&quot;">​</a></h2><ul><li>Grupos de trabajo (2 a 3 estudiantes).</li><li><strong>A cada grupo se le asignará un entorno de Sistema Operativo</strong> para su investigación y práctica: <strong>Grupo A (Windows)</strong> o <strong>Grupo B (Linux/Termux en Android)</strong>.</li></ul><hr><h2 id="📖-parte-i-defensa-teorica" tabindex="-1">📖 PARTE I: Defensa Teórica <a class="header-anchor" href="#📖-parte-i-defensa-teorica" aria-label="Permalink to &quot;📖 PARTE I: Defensa Teórica&quot;">​</a></h2><p>Basándose en el material &quot;Lectura_Catedra_Evaluacion_3&quot;, el grupo deberá exponer de forma concisa y clara los siguientes puntos antes de la demostración:</p><ol><li><strong>El Rol del SysAdmin:</strong></li><li><strong>Servicios Estructurales:</strong> Explicar cómo interactúan el servicio <strong>DHCP</strong> y el servicio <strong>DNS</strong> en una red real.</li><li><strong>Transferencia de Archivos:</strong> <strong>FTP/SFTP</strong> y <strong>Samba/SMB</strong>.</li><li><strong>Acceso Remoto Seguro:</strong> acceso remoto con ssh .</li></ol><hr><h2 id="💻-parte-ii-demostracion-practica-el-reto-nginx" tabindex="-1">💻 PARTE II: Demostración Práctica (El Reto Nginx) <a class="header-anchor" href="#💻-parte-ii-demostracion-practica-el-reto-nginx" aria-label="Permalink to &quot;💻 PARTE II: Demostración Práctica (El Reto Nginx)&quot;">​</a></h2><p>El grupo deberá investigar, preparar y mostrar <strong>en vivo</strong> la puesta en marcha de un servidor web <strong>Nginx</strong> en su sistema operativo asignado. <strong>No se permiten herramientas empaquetadas (como XAMPP o WAMP)</strong>; deben investigar cómo desplegar Nginx puro.</p><h3 id="🚀-requisitos-de-la-demostracion-para-ambos-grupos" tabindex="-1">🚀 Requisitos de la Demostración para AMBOS Grupos: <a class="header-anchor" href="#🚀-requisitos-de-la-demostracion-para-ambos-grupos" aria-label="Permalink to &quot;🚀 Requisitos de la Demostración para AMBOS Grupos:&quot;">​</a></h3><p>Durante la evaluación presencial, el grupo deberá demostrar al profesor lo siguiente:</p><ol><li><strong>Despliegue y Arranque:</strong> Demostrar cómo se inicia el servicio del servidor web Nginx en su entorno (Windows o Linux/Termux).</li><li><strong>Alojamiento del Mini-sitio:</strong> El servidor debe estar configurado para alojar un <strong>sitio web compuesto por exactamente tres (3) páginas HTML básicas</strong>. <ul><li>Estas páginas deben estar <strong>conectadas entre sí mediante enlaces (links)</strong> (ej. un menú de navegación básico para ir de una a otra).</li><li>La página de inicio debe contener los nombres y cédulas de los integrantes.</li></ul></li><li><strong>Prueba de Red Local:</strong> El grupo debe averiguar la dirección IP de su máquina servidora. El profesor se conectará a la misma red Wi-Fi y probará el acceso a la página web <strong>desde su propio dispositivo</strong>, navegando por los diferentes enlaces para comprobar el enrutamiento correcto de los archivos.</li><li><strong>Detención del Servicio:</strong> Al finalizar, el grupo debe demostrar cómo se apaga o detiene correctamente el servicio de Nginx en su sistema operativo.</li></ol><h3 id="🔍-temas-de-investigacion-por-grupo" tabindex="-1">🔍 Temas de Investigación por Grupo: <a class="header-anchor" href="#🔍-temas-de-investigacion-por-grupo" aria-label="Permalink to &quot;🔍 Temas de Investigación por Grupo:&quot;">​</a></h3><p><strong>Grupo A (Entorno Windows):</strong></p><ul><li>¿Cómo se descarga y ejecuta el binario de Nginx nativo en Windows?</li><li>¿En qué carpeta deben ubicarse los archivos HTML para que Nginx los lea por defecto en este entorno?</li><li>¿Cómo se averigua la IP en Windows y cómo se asegura que el Firewall local permita el tráfico entrante al puerto 80?</li><li>¿Cómo se detiene el proceso de un servidor que corre en segundo plano en Windows?</li></ul><p><strong>Grupo B (Entorno Linux / Termux en Android):</strong></p><ul><li>¿Cómo se instala Nginx usando los repositorios oficiales por línea de comandos?</li><li>¿Cuál es la ruta (directorio) por defecto donde Linux (o Termux) espera encontrar los archivos web públicos?</li><li>¿Cómo se crean y editan archivos HTML directamente desde la terminal (consola)?</li><li>¿Cómo se gestiona (inicia/detiene) el servicio de Nginx mediante comandos?</li></ul><hr><h2 id="⚖️-criterios-de-evaluacion-rubrica" tabindex="-1">⚖️ Criterios de Evaluación (Rúbrica) <a class="header-anchor" href="#⚖️-criterios-de-evaluacion-rubrica" aria-label="Permalink to &quot;⚖️ Criterios de Evaluación (Rúbrica)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Criterio</th><th style="text-align:left;">Descripción</th><th style="text-align:left;">Ponderación</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Investigación y Despliegue</strong></td><td style="text-align:left;">El grupo logró descubrir cómo levantar Nginx en su entorno sin usar instaladores gráficos pre-empaquetados.</td><td style="text-align:left;">30%</td></tr><tr><td style="text-align:left;"><strong>Enrutamiento (HTML)</strong></td><td style="text-align:left;">El mini-sitio de 3 páginas carga correctamente, y los enlaces internos usan rutas relativas válidas.</td><td style="text-align:left;">20%</td></tr><tr><td style="text-align:left;"><strong>Accesibilidad Externa</strong></td><td style="text-align:left;">La página es visible por el profesor desde otro dispositivo en la red (correcto manejo de IP/Puertos/Firewall).</td><td style="text-align:left;">25%</td></tr><tr><td style="text-align:left;"><strong>Dominio Teórico</strong></td><td style="text-align:left;">Claridad en la defensa de la Parte I y uso correcto del vocabulario técnico.</td><td style="text-align:left;">25%</td></tr></tbody></table>',24)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
